// Changes data: new NDA request from A + refusal by B + bell notices (cannot be deleted). Never approves.
import { test, expect } from '../../fixtures';
import { PAIR, SKIP_MSG, openChat, ensurePending, bRefuses, expectComposerBlocked, aRefusedBar, aWaitingBar, bRefusedBar, bellText } from './_pair';

test.describe.configure({ mode: 'serial' });

test.describe('NDA between headhunters — refusal shown in the chat (#d0bc44 #fb0f43)', () => {
  test.skip(!PAIR.enabled, SKIP_MSG);

  test('B refuses → A sees refusal bar + «שליחת בקשה חוזרת», bell «…ולכן הפנייה לא נשלחה»; both composers blocked @desktop @data #d0bc44 #fb0f43', async ({ asUser }) => {
    test.setTimeout(240_000);
    const a = await asUser(PAIR.a);
    const b = await asUser(PAIR.b);

    // 1. A: pending request (re-request if refused)
    const state = await ensurePending(a);
    test.skip(state === 'in-force', 'pair NDA is in force — need a pair without NDA (see specs/hunter-nda.md)');
    await expectComposerBlocked(a, 'A waiting'); // #fb0f43 п.1

    // 2. B: request bar, blocked composer, refuse
    await bRefuses(b);

    // 3. B after refusal: own bar, «אישור ה-NDA», composer blocked (#fb0f43 п.2)
    await b.reload();
    await expect(bRefusedBar(b)).toBeVisible({ timeout: 30_000 });
    await expect(b.getByText('כדי לכתוב, יש לאשר את ה-NDA')).toBeVisible();
    await expect(b.getByRole('button', { name: 'אישור ה-NDA' })).toBeVisible();
    await expectComposerBlocked(b, 'B after refusal');

    // 4. A after refusal: refusal bar instead of the first-contact popup (#d0bc44 п.1)
    await openChat(a);
    await expect(aRefusedBar(a)).toBeVisible({ timeout: 30_000 });
    await expect(a.getByText('אפשר לבקש שוב')).toBeVisible();
    await expect(a.getByRole('button', { name: 'שליחת בקשה חוזרת' })).toBeVisible();
    await expect(a.getByText('זו הפנייה הראשונה שלכם')).toHaveCount(0);
    await expect(aWaitingBar(a)).toHaveCount(0);
    await expectComposerBlocked(a, 'A after refusal');

    // 5. A bell: chat trigger wording (#d0bc44 п.3)
    const bell = await bellText(a);
    expect(bell, 'bell: «<B> סירבו …, ולכן הפנייה לא נשלחה»').toMatch(
      new RegExp(`${PAIR.bName} סירבו[^\\n]*ולכן הפנייה לא נשלחה`),
    );
  });
});
